        privacy: { overline: "Privacybeleid", title: "Privé door architectuur, niet door belofte.", intro: "Hoe SoraFiles met je gegevens omgaat — geschreven om exact overeen te komen met het gedrag van de app. Laatst herzien: 2026.", cards: [], sections: [{ h: "1. Bestanden worden lokaal verwerkt", p: "Geselecteerde bestanden worden in het geheugen van je browser gelezen en op je apparaat verwerkt. Ze worden niet geüpload naar SoraFiles of een conversiedienst; resultaten zijn aparte downloads en originelen worden nooit gewijzigd." }, { h: "2. Geen accounts", p: "SoraFiles vereist geen registratie en slaat geen gebruikersprofielen op." }, { h: "3. Lokale voorkeuren", p: "Je taal- en themakeuze wordt alleen in de lokale opslag van je browser bewaard." }, { h: "4. Advertenties", p: "Eén advertentieslot van een derde partij (highperformanceformat.com) kan gewone netwerkverzoeken doen terwijl je online bent. Het ontvangt geen bestandsnamen, -inhoud of verwerkingsgegevens, en tools wachten er nooit op." }, { h: "5. Analytics", p: "Deze versie van SoraFiles gebruikt geen Google Analytics of andere gebruiksstatistieken." }, { h: "6. Offline gebruik", p: "Na het eerste laden slaat een service worker de app op zodat kernfuncties zonder internet werken. Je bestanden worden nooit in een cache geschreven." }, { h: "7. Contact", p: "E-mail opent je eigen mailapp; verzenden is een online actie tussen jou en je provider." }] },
        terms: { overline: "Servicevoorwaarden", title: "Eerlijke voorwaarden, helder geschreven.", intro: "De regels voor het gebruik van SoraFiles. Laatst herzien: 2026.", cards: [], sections: [{ h: "1. De dienst", p: "SoraFiles biedt gratis browsergebaseerde PDF- en beeldtools, zoals ze zijn, zonder garanties." }, { h: "2. Jouw bestanden", p: "Je behoudt alle rechten op je bestanden en de gegenereerde resultaten. SoraFiles claimt geen eigendom, en jij bent verantwoordelijk voor het recht om de geselecteerde bestanden te verwerken." }, { h: "3. Redelijk gebruik", p: "Gebruik de tools legaal en probeer de dienst niet te verstoren." }, { h: "4. Realistische verwachtingen", p: "Browser- en apparaatmogelijkheden beïnvloeden de verwerking; conversies kunnen lay-out of getrouwheid veranderen. Controleer resultaten voordat je erop vertrouwt." }, { h: "5. Wijzigingen", p: "Belangrijke wijzigingen in deze voorwaarden worden op deze pagina gepubliceerd." }] },
