        privacy: { overline: "Polityka prywatności", title: "Prywatna z architektury, nie z obietnicy.", intro: "Jak SoraFiles traktuje Twoje dane — napisane tak, by dokładnie odpowiadało działaniu aplikacji. Przegląd: 2026.", cards: [], sections: [{ h: "1. Pliki przetwarzane lokalnie", p: "Wybrane pliki są wczytywane do pamięci przeglądarki i przetwarzane na Twoim urządzeniu. Nie są wysyłane do SoraFiles ani żadnej usługi konwersji; wyniki to osobne pliki do pobrania, a oryginały nigdy nie są modyfikowane." }, { h: "2. Bez kont", p: "SoraFiles nie wymaga rejestracji i nie przechowuje profili użytkowników." }, { h: "3. Lokalne preferencje", p: "Język i motyw są zapisywane tylko w lokalnej pamięci Twojej przeglądarki." }, { h: "4. Reklamy", p: "Jedno miejsce reklamowe strony trzeciej (highperformanceformat.com) może wykonywać zwykłe żądania sieciowe, gdy jesteś online. Nie otrzymuje nazw, treści ani danych plików, a narzędzia nigdy na nie nie czekają." }, { h: "5. Analityka", p: "Ta wersja SoraFiles nie używa Google Analytics ani żadnej analityki użycia." }, { h: "6. Praca offline", p: "Po pierwszym załadowaniu service worker zapisuje aplikację, więc główne funkcje działają bez internetu. Twoje pliki nigdy nie trafiają do pamięci podręcznej." }, { h: "7. Kontakt", p: "E-mail otwiera Twoją aplikację pocztową; wysłanie wiadomości to działanie online między Tobą a dostawcą poczty." }] },
